<header class="page-heading"><div><a class="back-link" href="<?= e(url('executive_recognition',['status'=>'all'])) ?>">Back to Hall of Fame</a><h1><?= $recognition?'Edit recognition':'Recognize executive service' ?></h1><p><?= e(\App\Executives\OrganizationService::label($appointment)) ?> &middot; <?= e($appointment['member_name_snapshot']) ?> · <?= e($appointment['position_name_snapshot']) ?> · <?= e($appointment['jurisdiction_snapshot']) ?></p></div></header>
<section class="card"><div class="card-body"><p class="text-secondary">This recognition is tied to completed appointment #<?= e($appointment['id']) ?>. Save as a draft while preparing it. Publishing makes it visible to signed-in staff; returning it to Draft removes it from their Hall of Fame.</p><form method="post" action="<?= e(url('executive_recognition_edit',['appointment_id'=>$appointment['id']])) ?>"><?= csrf() ?><input type="hidden" name="_action" value="executive_recognition_save"><input type="hidden" name="appointment_id" value="<?= e($appointment['id']) ?>"><input type="hidden" name="version" value="<?= e($recognition['updated_at']??'') ?>"><?= input('title','Recognition title',$values['title'],'text',true,'maxlength="160"') ?><div class="mb-3"><label class="form-label" for="recognition-citation">Citation</label><textarea class="form-control" id="recognition-citation" name="citation" maxlength="2000" rows="4" required><?= e($values['citation']) ?></textarea></div><div class="mb-3"><label class="form-label" for="recognition-achievements">Achievements (optional)</label><textarea class="form-control" id="recognition-achievements" name="achievements" maxlength="4000" rows="5"><?= e($values['achievements']??'') ?></textarea></div><div class="row"><div class="col-md-4"><?= input('recognized_on','Recognition date',$values['recognized_on'],'date',true,'max="'.gmdate('Y-m-d').'"') ?></div><div class="col-md-4"><?= input('display_order','Display order',$values['display_order'],'number',true,'min="0" max="65535" step="1"') ?></div><div class="col-md-4"><?= select_field('is_published','Publication',['0'=>'Draft','1'=>'Published'],$values['is_published']) ?></div></div><button class="btn btn-primary">Save recognition</button> <a class="btn btn-light" href="<?= e(url('executive_recognition',['status'=>'all'])) ?>">Cancel</a></form></div></section>
